import React from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../styles/UserPages.css";

const AdminDashboard = () => {
  const navigate = useNavigate();

  return (
    <div className="dashboard-wrapper">
      <Navbar />

      <div className="dashboard-layout">
        {/* Sidebar */}
        <aside className="dashboard-sidebar">
          <h3 className="sidebar-title">Admin Panel</h3>
          <div className="quick-buttons">
            <button onClick={() => navigate("/admin/users")} className="sidebar-btn">
              👥 Manage Users
            </button>
            <button onClick={() => navigate("/admin/reports")} className="sidebar-btn">
              📝 View Reports
            </button>
            <button onClick={() => navigate("/admin/flagged-listings")} className="sidebar-btn">
              🚩 Flagged Listings
            </button>
          </div>
        </aside>

        {/* Main Content */}
        <main className="dashboard-main" style={{ padding: "32px 48px" }}>
          <h2 style={{ textAlign: "center", marginBottom: "32px" }}>Welcome, Admin 👋</h2>
          <p style={{ textAlign: "center", color: "#444", fontSize: "16px" }}>
            Use the panel on the left to manage flagged listings, review user activity, and respond to reports.
          </p>
        </main>
      </div>

      <Footer />
    </div>
  );
};

export default AdminDashboard;
